import java.util.Map;

import static org.junit.Assert.*;

public class ObjectNode_setAll_TriageGen2Test {

    private JsonNodeFactory factory;
    private ObjectNode objectNode;

    @Before
    public void setUp() {
        factory = JsonNodeFactory.instance;
        objectNode = factory.objectNode();
    }

    @Test
    public void testSetAllWithValidValues() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("key1", factory.textNode("value1"));
        properties.put("key2", factory.numberNode(123));
        properties.put("key3", factory.booleanNode(true));

        JsonNode result = objectNode.setAll(properties);

        // Verify return type and fluent API (returns this)
        assertSame("setAll should return the same ObjectNode instance", objectNode, result);

        // Verify content
        assertEquals(3, objectNode.size());
        assertEquals("value1", objectNode.get("key1").asText());
        assertEquals(123, objectNode.get("key2").asInt());
        assertTrue(objectNode.get("key3").asBoolean());
    }

    @Test
    public void testSetAllWithNullValues() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("key1", factory.textNode("value1"));
        properties.put("keyNull", null); // This triggers the if (n == null) branch

        JsonNode result = objectNode.setAll(properties);

        assertSame(objectNode, result);
        assertEquals(2, objectNode.size());
        assertEquals("value1", objectNode.get("key1").asText());

        // Verify that null in map is converted to NullNode
        assertTrue("Null value in map should be converted to NullNode", objectNode.get("keyNull").isNull());
    }

    @Test
    public void testSetAllOverwritesExistingKeys() {
        // Pre-populate
        objectNode.put("existingKey", "oldValue");
        objectNode.put("otherKey", "stay");

        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("existingKey", factory.textNode("newValue"));
        properties.put("newKey", factory.textNode("brandNew"));

        objectNode.setAll(properties);

        assertEquals(3, objectNode.size());
        assertEquals("newValue", objectNode.get("existingKey").asText());
        assertEquals("stay", objectNode.get("otherKey").asText());
        assertEquals("brandNew", objectNode.get("newKey").asText());
    }

    @Test
    public void testSetAllWithEmptyMap() {
        Map<String, JsonNode> properties = new HashMap<>();

        objectNode.put("key", "value");
        int initialSize = objectNode.size();

        JsonNode result = objectNode.setAll(properties);

        assertSame(objectNode, result);
        assertEquals(initialSize, objectNode.size());
        assertEquals("value", objectNode.get("key").asText());
    }

    @Test
    public void testSetAllWithMixedNullAndNonNull() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("a", factory.textNode("a"));
        properties.put("b", null);
        properties.put("c", factory.nullNode()); // Explicit null node is different from Java null

        objectNode.setAll(properties);

        assertEquals(3, objectNode.size());
        assertFalse(objectNode.get("a").isNull());
        assertTrue(objectNode.get("b").isNull());
        assertTrue(objectNode.get("c").isNull());
    }
}
