        // Case: baseType.isContainerType() && isMapLikeType() && subclass is well-known Map
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);

        JavaType result = typeFactory.constructSpecializedType(baseType, HashMap.class);
        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());

        // Test LinkedHashMap
        JavaType result2 = typeFactory.constructSpecializedType(baseType, LinkedHashMap.class);
        assertEquals(LinkedHashMap.class, result2.getRawClass());

        // Test TreeMap
        JavaType result3 = typeFactory.constructSpecializedType(baseType, TreeMap.class);
        assertEquals(TreeMap.class, result3.getRawClass());
    }

