        assertNotNull(result);
        assertEquals(MyMap.class, result.getRawClass());
    }

    @Test
    public void testInterfaceRefinement() {
        // Base is an interface
        JavaType baseType = typeFactory.constructSimpleType(Iterable.class, null);
        // Subclass is ArrayList
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
    }

