package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import java.io.IOException;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TokenBuffer#deserialize.
 */
public class TokenBuffer_deserialize_TriageGen2Test {

    private ObjectMapper mapper;
    private DeserializationContext ctxt;
    private JsonParser jp;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        ctxt = mock(DeserializationContext.class);
        jp = mock(JsonParser.class);
    }

    @Test
    public void testDeserializeReturnsSelf() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // The method should return 'this' (the same instance)
        TokenBuffer result = buffer.deserialize(jp, ctxt);

        assertSame("deserialize should return the same TokenBuffer instance", buffer, result);
    }

    @Test
    public void testDeserializeCallsCopyCurrentStructure() throws IOException {
        // We need to spy on the TokenBuffer to verify that copyCurrentStructure is called
        // because copyCurrentStructure is a method in the same class.
        TokenBuffer buffer = spy(new TokenBuffer(mapper));

        // Execute
        buffer.deserialize(jp, ctxt);

        // Verify that copyCurrentStructure was called with the provided JsonParser
        verify(buffer, times(1)).copyCurrentStructure(jp);
    }

    @Test
    public void testDeserializeThrowsIOExceptionWhenCopyFails() throws IOException {
        TokenBuffer buffer = spy(new TokenBuffer(mapper));

        // Simulate an IOException being thrown during copyCurrentStructure
        doThrow(new IOException("Simulated IO Error")).when(buffer).copyCurrentStructure(jp);

        try {
            buffer.deserialize(jp, ctxt);
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }
    }

    @Test
    public void testDeserializeWithExistingTokens() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        // Add some initial content to the buffer
        buffer.writeStartObject();
        buffer.writeFieldName("test");
        buffer.writeString("value");
        buffer.writeEndObject();

        // Mock the parser to represent a field name (the special case mentioned in comments)
        // Even if the parser is at a FIELD_NAME, deserialize should call copyCurrentStructure
        when(jp.currentToken()).thenReturn(JsonToken.FIELD_NAME);
        when(jp.currentName()).thenReturn("test");

        TokenBuffer result = buffer.deserialize(jp, ctxt);

        assertSame(buffer, result);
        // Verification of content depends on copyCurrentStructure behavior, 
        // but the primary logic of deserialize is returning 'this'.
    }
}
