package com.fasterxml.jackson.databind.util;

import org.junit.Before;
import org.junit.Test;
import java.text.ParseException;
import java.text.ParsePosition;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat#parseAsISO8601.
 * Since the method is protected, we use a subclass to access it.
 */
public class StdDateFormat_parseAsISO8601_TriageGen0Test {

    private TestableStdDateFormat dateFormat;

    // Subclass to expose protected method for testing
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(TimeZone tz, Locale loc, boolean lenient) {
            super(tz, loc);
            setLenient(lenient);
        }

        @Override
        public Date parseAsISO8601(String dateStr, ParsePosition pos, boolean throwErrors) throws ParseException {
            return super.parseAsISO8601(dateStr, pos, throwErrors);
        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParsePlainDate() throws ParseException {
        // len <= 10 and last char is digit
        Date result = dateFormat.parseAsISO8601("2023-10-27", new ParsePosition(0), true);
        Calendar cal = Calendar.getInstance();
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(27, cal.get(Calendar.DAY_OF_MONTH));
    }

    @Test
    public void testParseZuluWithMissingMillis() throws ParseException {
        // Ends with Z, but has ':' at len-4
        // Input: 2023-10-27T10:00:00Z -> length 20, len-4 is ':'
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00Z", new ParsePosition(0), true);
        assertNotNull(result);
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseZuluWithMillis() throws ParseException {
        // Ends with Z, but doesn't trigger the 'missing millis' branch
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00.123Z", new ParsePosition(0), true);
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetAndColon() throws ParseException {
        // hasTimeZone is true, contains ':' at len-3
        // Input: 2023-10-27T10:00:00+05:00 -> removes colon -> 2023-10-27T10:00:00+0500
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00+05:00", new ParsePosition(0), true);
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetMissingMinutes() throws ParseException {
        // hasTimeZone is true, c at len-3 is '+' or '-'
        // Input: 2023-10-27T10:00:00+05 -> appends '00'
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00+05", new ParsePosition(0), true);
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneAndVaryingTimeLengths() throws ParseException {
        // Test various branches in the timeLen < 12 block

        // case 11: 2023-10-27T10:00:00+05 (len-T-6 = 11)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00+05", new ParsePosition(0), true));

        // case 10: 2023-10-27T10:00:0+05 (len-T-6 = 10)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:0+05", new ParsePosition(0), true));

        // case 9: 2023-10-27T10:00:+05 (len-T-6 = 9)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:+05", new ParsePosition(0), true));

        // case 8: 2023-10-27T10:00+05 (len-T-6 = 8)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00+05", new ParsePosition(0), true));

        // case 6: 2023-10-27T10:0+05 (len-T-6 = 6)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:0+05", new ParsePosition(0), true));

        // case 5: 2023-10-27T10+05 (len-T-6 = 5)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10+05", new ParsePosition(0), true));
    }

    @Test
    public void testParseNoTimeZoneAppendsZulu() throws ParseException {
        // hasTimeZone is false, appends 'Z'
        // Input: 2023-10-27T10:00:00
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00", new ParsePosition(0), true);
        assertNotNull(result);

        // Test timeLen < 12 without timezone (append .000)
        // Input: 2023-10-27T10:00 (len-T-1 = 5)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00", new ParsePosition(0), true));

        // Input: 2023-10-27T10:00:0 (len-T-1 = 7) -> case 7 (no action)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:0Z", new ParsePosition(0), true));
    }

    @Test(expected = ParseException.class)
    public void testParseFailureThrowsException() throws ParseException {
        // Force a failure by passing invalid date string with non-lenient
        dateFormat = new TestableStdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US, false);
        dateFormat.parseAsISO8601("not-a-date", new ParsePosition(0), true);
    }

    @Test
    public void testParseWithNullDtThrowsException() {
        // Testing the dt == null block for non-lenient
        dateFormat = new TestableStdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US, false);
        // Using a string that might pass the logic but fail the actual DateFormat.parse
        // depending on internal state. Since we can't easily mock the internal df, 
        // we rely on the fact that if it returns null, it throws.
        ParsePosition pos = new ParsePosition(0);
        // "invalid" will likely fail parsing.
        try {
            dateFormat.parseAsISO8601("invalid", pos, true);
            fail("Should have thrown ParseException");
        } catch (ParseException e) {
            assertTrue(e.getMessage().contains("Can not parse date"));
        }
    }

    @Test
    public void testLenientMode() throws ParseException {
        // Test that lenient mode allows slightly off dates if the underlying DateFormat supports it
        dateFormat = new TestableStdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US, true);
        Date result = dateFormat.parseAsISO8601("2023-13-01T10:00:00Z", new ParsePosition(0), true);
        assertNotNull(result);
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.setTime(result);
        // Month 13 -> Jan of next year
        assertEquals(2024, cal.get(Calendar.YEAR));
        assertEquals(Calendar.JANUARY, cal.get(Calendar.MONTH));
    }
}
