    /**
     * Tests a successful Cholesky decomposition of a symmetric positive definite matrix.
     * This covers the main success path and the mathematical transformation logic.
     */
    @Test
    public void testConstructor_Success() throws Exception {
        double[][] data = {
            {4.0, 12.0, -16.0},
            {12.0, 37.0, -43.0},
            {-16.0, -43.0, 98.0}
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);
        double relativeSymmetryThreshold = 1e-10;
        double absolutePositivityThreshold = 1e-10;

        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(
            matrix, relativeSymmetryThreshold, absolutePositivityThreshold);

        assertNotNull(decomposition.getL());
        assertNotNull(decomposition.getLT());
        // Check determinant (det(A) = det(L)*det(L^T))
        // For this matrix, det is 4 * (37*98 - 43*43) - 12 * (12*98 - (-43*-16)) + (-16) * (12*-43 - 37*-16)
        // A more reliable way is to check if L * LT = A
        RealMatrix L = decomposition.getL();
        RealMatrix LT = decomposition.getLT();
        RealMatrix reconstructed = L.multiply(LT);

        for (int i = 0; i < data.length; i++) {
            for (int j = 0; j < data[0].length; j++) {
                assert(Math.abs(reconstructed.getEntry(i, j) - data[i][j]) < 1e-9);
            }
        }
    }

    /**
     * Tests the exception when the matrix is not square.
     */
    @Test(expected = NonSquareMatrixException.class)
    public void testConstructor_NonSquareMatrix() throws Exception {
