     */
    @Test(expected = NotSymmetricMatrixException.class)
    public void testConstructor_NotSymmetricMatrix() throws Exception {
        double[][] data = {
            {4.0, 1.0},
            {2.0, 4.0} // 1.0 != 2.0
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);
        // Using a very small threshold to ensure it triggers the exception
        new CholeskyDecompositionImpl(matrix, 1e-10, 1e-10);
    }

    /**
