     */
    @Test(expected = NotPositiveDefiniteMatrixException.class)
    public void testConstructor_NotPositiveDefinite_Diagonal() throws Exception {
        double[][] data = {
            {0.00000000001, 0.0},
            {0.0, 1.0}
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);
        // Threshold is higher than the diagonal element
        new CholeskyDecompositionImpl(matrix, 1e-10, 1e-5);
    }

